import assert from "node:assert/strict";
import test from "node:test";
import { readStream } from "../src/shared/stream.ts";
import { emptyReply, reduceReply } from "../src/shared/transcript.ts";
import { UiError } from "../src/shared/i18n.ts";
import type { StreamChunk } from "../src/shared/protocol.ts";
import { contract } from "./contract-fixture.ts";

// This payload is generated by the actual Python projector, not a second frontend implementation.
test("backend messages are idempotent complete replacements across stream and history", () => {
  const payload = contract.messages[0];
  const progress = reduceReply(emptyReply(), {
    chunk_type: "data",
    chunk: payload,
  });
  assert.equal(progress.content, "Hello");
  assert.equal(progress.outcome, "completed");
  assert.deepEqual(
    reduceReply(progress, { chunk_type: "data", chunk: payload }),
    progress,
  );
  assert.throws(() =>
    reduceReply(progress, { chunk_type: "error", chunk: "Connection lost" }),
  );
});

test("SSE decodes fragmented UTF-8 and CRLF; EOF never implies successful completion", async () => {
  const bytes = new TextEncoder().encode(
    'data: {"chunk_type":"content","chunk":"你好"}\r\n\r\ndata: [DONE]\r\n\r\n',
  );
  const stream = new ReadableStream<Uint8Array>({
    start(controller) {
      for (const byte of bytes) controller.enqueue(new Uint8Array([byte]));
      controller.close();
    },
  });
  const chunks: StreamChunk[] = [];
  await readStream(stream, (chunk) => chunks.push(chunk));
  assert.deepEqual(
    chunks.map((chunk) => chunk.chunk_type),
    ["content", "done"],
  );
  assert.equal(chunks[0].chunk, "你好");
  const partial = new ReadableStream<Uint8Array>({
    start(controller) {
      controller.enqueue(
        new TextEncoder().encode(
          'data: {"chunk_type":"content","chunk":"partial"}\n\n',
        ),
      );
      controller.close();
    },
  });
  await assert.rejects(
    readStream(partial, () => {}),
    (error: unknown) =>
      error instanceof UiError && error.key === "streamInterrupted",
  );
});
